#include "../core/UI/InterfazGrafica.h"
#include "core/Planificador/Planificador.h"
#include <QAbstractItemView>
#include <QDialog>
#include <QDialogButtonBox>
#include <QFormLayout>
#include <QHBoxLayout>
#include <QHeaderView>
#include <QLabel>
#include <QListWidget>
#include <QButtonGroup>
